class Solution {
public:
    vector<string> sortPeople(vector<string>& names, vector<int>& heights) {
        int n = names.size();
        vector<pair<int,int>> v(n);
        for (int i = 0; i < n; i++) {
            v[i] = {heights[i], i};
        }
        sort(v.begin(), v.end(), [](const pair<int,int>& a, const pair<int,int>& b){
            return a.first > b.first;
        });
        vector<string> res(n);
        for (int i = 0; i < n; i++) {
            res[i] = names[v[i].second];
        }
        return res;
    }
};
